import hashlib, os

class Guarded:
    def __init__(self, v):
        self._key = int.from_bytes(os.urandom(4), "little")
        self.set(v)
    def _tag(self, enc):
        return hashlib.sha256((enc ^ self._key).to_bytes(8, "little", signed=True)).digest()[:4]
    def set(self, v):
        self._enc = v ^ self._key
        self._chk = self._tag(self._enc)
    def get(self):
        if self._tag(self._enc) != self._chk:
            raise RuntimeError("tamper detected")
        return self._enc ^ self._key

gold = Guarded(1000)
print("정상 읽기:", gold.get())
print("메모리에 1000 이 그대로 있나:", gold._enc == 1000)
gold._enc = 999999   # 메모리 편집기로 덮었다고 치자
try:
    gold.get()
except RuntimeError as e:
    print("변조 뒤 읽기:", e)

# 출력
# 정상 읽기: 1000
# 메모리에 1000 이 그대로 있나: False
# 변조 뒤 읽기: tamper detected
